            List<BudsInfo> readBuds;List<BluetoothPeer> readPeers;lock(gate){readBuds=budRows.ToList();readPeers=peers.ToList();}var pnpBattery=readBuds.Select(b=>BudsDeviceData.Battery(b.Container,b.Name)).Where(b=>b.HasValue).Select(b=>b.Value).Distinct().ToArray();int productImages=readBuds.Count(b=>BudsDeviceData.Picture(b.Name)!=null);
